<aside class="sidebar" aria-label="<?php esc_attr_e('Conteúdo complementar','gamezone'); ?>"><section class="panel"><h2 class="panel-title">🔥 <?php esc_html_e('Destaques da semana','gamezone'); ?></h2><div class="trending-list"><?php $trending=new WP_Query(array('posts_per_page'=>4,'ignore_sticky_posts'=>false,'no_found_rows'=>true));if($trending->have_posts()):while($trending->have_posts()):$trending->the_post(); ?><a href="<?php the_permalink(); ?>" class="trending-item"><span class="trending-thumb"><?php if(has_post_thumbnail())the_post_thumbnail('thumbnail');else echo '🎮'; ?></span><span><?php the_title(); ?></span></a><?php endwhile;wp_reset_postdata();else: ?><p class="empty-note"><?php esc_html_e('Publique artigos para mostrar destaques aqui.','gamezone'); ?></p><?php endif; ?></div></section><section class="panel"><h2 class="panel-title">▣ <?php esc_html_e('Categorias','gamezone'); ?></h2><ul class="category-list"><?php foreach(gamezone_categories() as $slug=>$label):$cat=get_category_by_slug($slug); ?><li><a href="<?php echo esc_url(gamezone_category_link($slug)); ?>"><span><?php echo esc_html($label); ?></span><span class="count"><?php echo $cat?esc_html($cat->count):'0'; ?></span></a></li><?php endforeach; ?></ul></section><?php if(is_active_sidebar('sidebar-1'))dynamic_sidebar('sidebar-1'); ?></aside>